				const ship = view.ship;
				const rule = readRuleValue(view.moduleState);
				if (!ship) return [{
					label: "Status",
					value: "No active vessel"
				}];
				const biome = typeof rule?.biome === "string" ? rule.biome : "Scanning...";
				const stratum = typeof rule?.stratum === "string" ? rule.stratum : "Crust";
				const targetMat = typeof rule?.targetMaterial === "string" ? rule.targetMaterial : "Regolith";
				const minedCount = typeof rule?.minedCount === "number" ? rule.minedCount : 0;
				const magmaHazard = Boolean(rule?.coreMagmaHazard ?? false);
				const eva0 = typeof rule?.eva0 === "object" && rule?.eva0 !== null && !Array.isArray(rule.eva0) ? rule.eva0 : null;
				const evaMode = String(eva0?.mode ?? "boarded");
				const evaTool = String(eva0?.activeTool ?? "drill");
				const o2 = Number(eva0?.oxygen ?? 100).toFixed(0);
				const battery = Number(eva0?.battery ?? 100).toFixed(0);
				const survival = typeof rule?.survival === "object" && rule?.survival !== null && !Array.isArray(rule.survival) ? rule.survival : null;
				const shipFuel = Number(survival?.shipFuelKg ?? 750).toFixed(0);
				const inv = typeof rule?.inventory === "object" && rule.inventory !== null && !Array.isArray(rule.inventory) ? rule.inventory : {};
				const fe = Number(inv.iron ?? 0);
				const cu = Number(inv.copper ?? 0);
				const ti = Number(inv.titanium ?? 0);
				const u = Number(inv.uranium ?? 0);
				const ice = Number(inv.ice ?? 0);
				const split = typeof rule?.splitScreen === "object" && rule?.splitScreen !== null && !Array.isArray(rule.splitScreen) ? rule.splitScreen : null;
				const splitActive = Boolean(split?.active ?? false);
				const splitSeparated = Boolean(split?.separated ?? false);
				const qb = typeof rule?.quickbar === "object" && rule?.quickbar !== null && !Array.isArray(rule.quickbar) ? rule.quickbar : { activeSlot: 0 };
				const activeSlotIdx = Number(qb.activeSlot ?? 0);
				const activeBlockName = QUICKBAR_NAMES[activeSlotIdx] ?? "Drill";
				const hab = typeof rule?.habitat === "object" && rule?.habitat !== null && !Array.isArray(rule.habitat) ? rule.habitat : null;
				const habSealed = Boolean(hab?.sealed ?? false);
				const habPress = Number(hab?.pressureKPa ?? 0).toFixed(1);
				const habGen = (Number(hab?.generationWatts ?? 0) / 1e3).toFixed(1);
				const habLoad = (Number(hab?.consumptionWatts ?? 0) / 1e3).toFixed(1);
				const nav = typeof rule?.navigation === "object" && rule?.navigation !== null && !Array.isArray(rule.navigation) ? rule.navigation : null;
				const navBody = String(nav?.bodyName ?? view.body.name ?? "Terra");
				const soiStatus = String(nav?.soiStatus ?? (view.body.id === "parvus" ? "LUNAR ENCOUNTER" : "ORBITAL"));
				const mu = view.body.mu ?? 72e6;
				const radius = view.body.radius ?? 1200;
				const surfaceG = typeof nav?.surfaceG === "number" ? nav.surfaceG : radius > 0 ? mu / (radius * radius) : 50;
				const apoapsis = typeof nav?.apoapsis === "number" ? nav.apoapsis : 0;
				const periapsis = typeof nav?.periapsis === "number" ? nav.periapsis : 0;
				return [
					{
						label: "Active World",
						value: `${navBody} (g = ${surfaceG.toFixed(1)} m/s²)`
					},
					{
						label: "SOI Status",
						value: soiStatus
					},
					{
						label: "Orbit Ap / Pe",
						value: `${(apoapsis / 1e3).toFixed(1)} km / ${(periapsis / 1e3).toFixed(1)} km`
					},
					{
						label: "EVA Avatar",
						value: evaMode.toUpperCase(),
						unit: evaMode === "boarded" ? "Cockpit" : "Suit"
					},
					{
						label: "Suit O2 / Battery",
						value: `${o2}% / ${battery}%`
					},
					{
						label: "Habitat Pressure",
						value: `${habPress} kPa`,
						unit: habSealed ? "Sealed" : "Vacuum"
					},
					{
						label: "Base Power Grid",
						value: `${habGen} kW / ${habLoad} kW`
					},
					{
						label: "Ship Fuel",
						value: `${shipFuel} kg`,
						unit: "Hydrolox"
					},
					{
						label: "Active Tool",
						value: evaTool === "laser" ? "Mining Laser (Raycast)" : "Mechanical Drill"
					},
					{
						label: "Active Block",
						value: `${activeBlockName} [Slot ${activeSlotIdx + 1}]`
					},
					{
						label: "Stratum / Biome",
						value: `${stratum} · ${biome}`
					},
					{
						label: "Drill Reticle",
						value: targetMat
					},
					{
						label: "Core Magma Warning",
						value: magmaHazard ? "CRITICAL THERMAL HAZARD" : "Nominal"
					},
					{
						label: "Mined Tiles",
						value: `${minedCount} blocks`
					},
					{
						label: "Fe / Cu / Ti / U / Ice",
						value: `${fe} / ${cu} / ${ti} / ${u} / ${ice}`
					},
					{
						label: "Split-Screen",
						value: splitActive ? splitSeparated ? "Dual Partition" : "Merged Co-op" : "Single View"
					}
