			}
		});
		context.contributeCamera({
			name: "horizon-eva",
			label: "Smooth Horizon EVA Camera",
			frame(input) {
				const ship = input.ship;
				if (!ship) return {
					center: input.body.position,
					rotation: 0
				};
				const rule = readRuleValue(input.moduleState);
				const eva0 = typeof rule?.eva0 === "object" && rule?.eva0 !== null && !Array.isArray(rule.eva0) ? rule.eva0 : null;
				const evaMode = String(eva0?.mode ?? "boarded");
				const rel = ship.state.position;
				const evaX = Number(eva0?.x ?? rel.x);
				const evaY = Number(eva0?.y ?? rel.y);
				const targetPos = evaMode !== "boarded" ? {
					x: evaX,
					y: evaY
				} : rel;
				const r = hypot(targetPos.x, targetPos.y);
				const bodyRadius = input.body.radius;
				const altitude = Math.max(0, r - bodyRadius);
				const blend = Math.max(0, Math.min(1, (250 - altitude) / 200));
				const isSubterraneanDeep = r < 50 || r < bodyRadius * .2;
				const horizonAngle = targetPos.x === 0 && targetPos.y === 0 || isSubterraneanDeep ? 0 : normalizeAngle(atan2(targetPos.y, targetPos.x) - Math.PI * .5);
