					x: input.body.position.x + evaX,
					y: input.body.position.y + evaY
				};
				const split = typeof rule?.splitScreen === "object" && rule?.splitScreen !== null && !Array.isArray(rule.splitScreen) ? rule.splitScreen : null;
				const isSplitActive = Boolean(split?.active ?? false);
				const isSeparated = Boolean(split?.separated ?? false);
				const ships = input.ships;
				const p2Ship = ships && ships.length > 1 ? ships[1] : void 0;
				if (isSplitActive && isSeparated && p2Ship) return { viewports: [{
					seatSlot: 0,
					center: evaMode !== "boarded" ? astronautPos : ship.position,
					rotation: -horizonAngle * blend,
					rect: {
						x: 0,
						y: 0,
						width: .5,
						height: 1
					}
				}, {
					seatSlot: 1,
					center: p2Ship.position,
					rotation: -horizonAngle * blend,
					rect: {
						x: .5,
						y: 0,
						width: .5,
						height: 1
					}
				}] };
				return {
					center: evaMode !== "boarded" ? astronautPos : ship.position,
					rotation: -horizonAngle * blend
				};
			}
		});
	}
